alter table private.customer_payment_methods add column if not exists storage_consent_version text,add column if not exists storage_consented_at timestamptz,add column if not exists storage_consent_source text;
alter table private.customer_payment_methods drop constraint if exists customer_payment_methods_storage_consent_consistency;
alter table private.customer_payment_methods add constraint customer_payment_methods_storage_consent_consistency check ((storage_consent_version is null and storage_consented_at is null and storage_consent_source is null) or (storage_consent_version is not null and storage_consented_at is not null and storage_consent_source is not null));
create or replace function public.store_verified_provider_payment_method_v2(p_user_id uuid,p_provider text,p_provider_customer_ref text,p_provider_payment_method_ref text,p_brand text,p_last4 text,p_exp_month smallint default null,p_exp_year smallint default null,p_billing_name text default null,p_nickname text default null,p_billing_country_code text default null,p_billing_postal_code text default null,p_make_default boolean default false,p_consent_version text default null,p_consent_source text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare method_id uuid; consent_version text:=btrim(coalesce(p_consent_version,'')); consent_source text:=btrim(coalesce(p_consent_source,'')); begin if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501'; end if; if char_length(consent_version) not between 3 and 80 or consent_version ~ '[[:cntrl:]]' then raise exception 'card_storage_consent_required' using errcode='22023'; end if; if char_length(consent_source) not between 3 and 80 or consent_source ~ '[[:cntrl:]]' then raise exception 'card_storage_consent_source_required' using errcode='22023'; end if; method_id:=public.store_verified_provider_payment_method_v1(p_user_id,p_provider,p_provider_customer_ref,p_provider_payment_method_ref,p_brand,p_last4,p_exp_month,p_exp_year,p_billing_name,p_nickname,p_billing_country_code,p_billing_postal_code,p_make_default); update private.customer_payment_methods set storage_consent_version=consent_version,storage_consented_at=timezone('utc',now()),storage_consent_source=consent_source,updated_at=timezone('utc',now()) where id=method_id and user_id=p_user_id; if not found then raise exception 'payment_method_store_failed' using errcode='55000'; end if; return method_id; end;$$;
revoke all on function public.store_verified_provider_payment_method_v1(uuid,text,text,text,text,text,smallint,smallint,text,text,text,text,boolean) from public,anon,authenticated,service_role;
revoke all on function public.store_verified_provider_payment_method_v2(uuid,text,text,text,text,text,smallint,smallint,text,text,text,text,boolean,text,text) from public,anon,authenticated;
grant execute on function public.store_verified_provider_payment_method_v2(uuid,text,text,text,text,text,smallint,smallint,text,text,text,text,boolean,text,text) to service_role;
